async function resendConfirmation(){if(busy||emailCooldown>0)return;setBusy(true);setError('');setNotice('');try{if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))throw new Error(t('Эхлээд имэйл хаягаа оруулна уу.','Enter your email address first.'));const db=await marketplaceClient();const r=await db.auth.resend({type:'signup',email:email.trim().toLowerCase(),options:{emailRedirectTo:location.origin+'/login/'}});if(r.error)throw r.error;setEmailCooldown(60);setNotice(t('Хүсэлт хүлээн авлаа. Имэйл хүргэгдсэнийг батлах боломжгүй. Өмнө бүртгүүлсэн бол Нэвтрэх эсвэл Нууц үг сэргээх сонголтыг ашиглана уу.','Request accepted; email delivery is not guaranteed. Already registered? Sign in or reset your password instead.'));}catch(e){fail(e)}finally{setBusy(false)}}
async function refreshMessages(){if(!uid||!role)return;const db=await marketplaceClient();const r=await db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').or('sender_id.eq.'+uid+',recipient_id.eq.'+uid).order('created_at',{ascending:false}).order('id',{ascending:false}).limit(500);if(r.error)throw r.error;const latest=r.data as ChatMessage[];setHasOlderMessages(latest.length===500);setMessages(previous=>mergeMessagePage(previous,latest))}
async function loadOlderMessages(){if(!uid||!role||olderMessagesLoading||!hasOlderMessages||!messages.length)return;setOlderMessagesLoading(true);try{const db=await marketplaceClient();const oldest=messages[0];const r=await db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').or('sender_id.eq.'+uid+',recipient_id.eq.'+uid).or('created_at.lt.'+oldest.created_at+',and(created_at.eq.'+oldest.created_at+',id.lt.'+oldest.id+')').order('created_at',{ascending:false}).order('id',{ascending:false}).limit(100);if(r.error)throw r.error;const older=r.data as ChatMessage[];setHasOlderMessages(older.length===100);setMessages(previous=>mergeMessagePage(previous,older))}catch(e){fail(e)}finally{setOlderMessagesLoading(false)}}
useEffect(()=>{
  if(!uid||!role)return;
  let active=true;
  let unsubscribe=()=>{};
  setRealtimeStatus('connecting');
  const sync=async()=>{
    const db=await marketplaceClient();
    const response=await db.from('messages')
      .select('id,sender_id,recipient_id,body,created_at,read_at')
      .or('sender_id.eq.'+uid+',recipient_id.eq.'+uid)
      .order('created_at',{ascending:false}).order('id',{ascending:false}).limit(500);
    if(!active||response.error)return;
    // Merge rather than overwrite events arriving while a fetch is in flight.
    setHasOlderMessages(previous=>previous||response.data.length===500);
    setMessages(existing=>{
      const own=existing.filter(message=>message.sender_id===uid||message.recipient_id===uid);
      return mergeMessagePage(own,response.data as ChatMessage[]);
    });
  };
  void marketplaceClient().then(db=>{
    if(!active)return;
    const accept=(payload:{new:Record<string,unknown>})=>{
      const message=payload.new as ChatMessage;
      if(!active||!message.id||!(message.sender_id===uid||message.recipient_id===uid))return;
      setMessages(list=>appendUniqueMessage(list,message));
    };
    const channel=db.channel('hustle-beta-inbox-'+uid)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'recipient_id=eq.'+uid},accept)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'sender_id=eq.'+uid},accept)
      .subscribe(status=>{
        if(!active)return;
        if(status==='SUBSCRIBED'){setRealtimeStatus('connected');void sync();}
        if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED')setRealtimeStatus('fallback');
      });
    unsubscribe=()=>{void db.removeChannel(channel)};
    void sync();
  }).catch(()=>{if(active)setRealtimeStatus('fallback')});
  // Missed network events and inactive tabs still converge on the DB.
  const interval=window.setInterval(()=>{if(active)void sync()},30000);
  return()=>{active=false;clearInterval(interval);unsubscribe()};
},[uid,role]);
function openChat(peerId:string){if(!peerId||peerId===uid)return;setChatPeer(peerId);setTab('messages');setError('');void markThreadRead(peerId)}
// A selected file is only a local draft. No upload, RPC or message is created until Send.
function stageChatFile(file:File){
 const invalid=validateChatFile(file);
 if(invalid){setError(invalid);return}
 setError('');
 setPendingChatFile(file);
}
useEffect(()=>{setPendingChatFile(null)},[uid,chatPeer]);
async function sendMessage(e:FormEvent<HTMLFormElement>){
 e.preventDefault();
 const body=normalizedMessage(chatDraft),file=pendingChatFile,recipient=chatPeer;
 if((!body&&!file)||!recipient||recipient===uid||busy||chatLoading||uploading)return;
 setChatLoading(true);setError('');
 try{
  // Upload first, then text. Clearing a successfully sent attachment before sending
  // text prevents accidental duplicate uploads if the text request fails.
  if(file){
   await attachFile(file,recipient);
   setPendingChatFile(current=>current===file?null:current);
  }
  if(body){
   const db=await marketplaceClient();
   const r=await db.from('messages').insert({sender_id:uid,recipient_id:recipient,body}).select('id,sender_id,recipient_id,body,created_at').single();
   if(r.error)throw r.error;
   setMessages(list=>appendUniqueMessage(list,r.data as ChatMessage));
   setChatDraft(current=>normalizedMessage(current)===body?'':current);
  }
 }catch(err){fail(err)}finally{setChatLoading(false)}
}
async function attachFile(file:File,recipient:string){
 const invalid=validateChatFile(file);
 if(invalid)throw new Error(invalid);
 setUploading(true);
 try{
  const db=await marketplaceClient();
  const extension=file.name.split('.').pop()?.toLowerCase()||'bin';
  const path=uid+'/'+recipient+'/'+crypto.randomUUID()+'.'+extension;
  const up=await db.storage.from('chat-attachments').upload(path,file,{contentType:file.type,upsert:false});
  if(up.error)throw up.error;
  const sent=await db.rpc('send_chat_attachment',{target_recipient:recipient,upload_path:path,display_name:file.name,mime:file.type,bytes:file.size});
  if(sent.error){
   try{await db.storage.from('chat-attachments').remove([path])}catch{}
   throw sent.error;
  }
  const [m,a]=await Promise.all([
   db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').eq('id',sent.data).single(),
   db.from('chat_attachments').select('*').eq('message_id',sent.data).single()
  ]);
  if(m.data)setMessages(list=>appendUniqueMessage(list,m.data as ChatMessage));
  if(a.data)setAttachments(list=>[...list,a.data as MessengerAttachment]);
  // The database message already succeeded; a transient UI refresh must not resend it.
  if(m.error||a.error)void refreshMessages().catch(()=>{});
 }finally{setUploading(false)}
}
async function openAttachment(a:MessengerAttachment){try{const db=await marketplaceClient();const url=await db.storage.from('chat-attachments').createSignedUrl(a.object_path,90);if(url.error)throw url.error;window.open(url.data.signedUrl,'_blank','noopener,noreferrer')}catch(e){fail(e)}}
async function markThreadRead(peer:string){if(!uid||!peer)return;const db=await marketplaceClient();const received=messages.filter(m=>m.sender_id===peer&&m.recipient_id===uid&&!(m as ChatMessage&{read_at?:string|null}).read_at);if(!received.length)return;const read=await db.from('messages').update({read_at:new Date().toISOString()}).in('id',received.map(m=>m.id));if(read.error)return;setMessages(old=>old.map(m=>received.some(r=>r.id===m.id)?{...m,read_at:new Date().toISOString()}:m));}
